    else {const yy=kind==='descent'?h*(.28+t*.33):kind==='reentry'?h*(.25+t*.25):h*.6;rocket(c,x,yy,.4,kind==='descent'?12:0);for(const side of [-1,1]) line(c,x+side*5,yy,x+side*17,yy+10,silver,2);
