    ellipse(c,x,y-21,23,24,'#dae4f24d');line(c,x-15,y-4,x+15,y-4,silver,2);ellipse(c,x-5,y-19,2,3,ink);ellipse(c,x+5,y-19,2,3,ink);c.fillStyle=amber;c.fillRect(x+19,y-8,8,4);
  } else {
